  {
    "start": 1,
    "subgoal": "Outline the scope of the lecture by introducing the issues and challenges in virtual and augmented reality systems."
  },
  {
    "start": 21,
    "subgoal": "Recall the definition and state the main objective of a Virtual Reality system."
  },
  {
    "start": 35,
    "subgoal": "Identify the two major challenges in VR: technological and psychological."
  },
  {
    "start": 58,
    "subgoal": "Define immersion and identify the six qualitative terms that characterize a VR experience."
  },
  {
    "start": 71,
    "subgoal": "Describe the six qualities (extensive, matching, surrounding, vivid, interactive, and plot informing) that contribute to immersion."
  },
  {
    "start": 126,
    "subgoal": "Explain how immersion represents the technological issue in creating a VR experience."
  },
  {
    "start": 134,
    "subgoal": "Define presence as a subjective psychological state experienced by the user in VR."
  },
  {
    "start": 153,
    "subgoal": "Compare and contrast immersion (objective) and presence (subjective), explaining how they relate to one another."
  },
  {
    "start": 171,
    "subgoal": "Explain why the overall goal of any VR system is to achieve a high degree of presence."
  },
  {
    "start": 181,
    "subgoal": "Preview the subsequent lectures, indicating that immersion and presence are not the only issues facing VR systems."
  }
]
